def macro_f1(y_true, y_pred):
    classes = sorted(set(y_true) | set(y_pred))
    f1s = []
    for c in classes:
        tp = sum(t == c and p == c for t, p in zip(y_true, y_pred))
        fp = sum(t != c and p == c for t, p in zip(y_true, y_pred))
        fn = sum(t == c and p != c for t, p in zip(y_true, y_pred))
        prec = tp / (tp + fp) if tp + fp else 0.0
        rec = tp / (tp + fn) if tp + fn else 0.0
        f1s.append(2 * prec * rec / (prec + rec) if prec + rec else 0.0)
    return sum(f1s) / len(f1s)

def rouge_l(candidate, reference):
    m, n = len(candidate), len(reference)
    if m == 0 or n == 0:
        return 0.0, 0.0, 0.0
    prev = [0] * (n + 1)                   # 上一行：candidate[:i-1] 与 reference[:j] 的 LCS
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            if candidate[i - 1] == reference[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    lcs = prev[n]
    if lcs == 0:
        return 0.0, 0.0, 0.0
    p, r = lcs / m, lcs / n
    return p, r, 2 * p * r / (p + r)

def _merge(ids, pair, new_id):
    out, i = [], 0
    while i < len(ids):
        if i + 1 < len(ids) and (ids[i], ids[i + 1]) == pair:
            out.append(new_id)
            i += 2
        else:
            out.append(ids[i])
            i += 1
    return out


def train_bpe(text, num_merges):
    ids = list(text.encode("utf-8"))
    merges = []
    for _ in range(num_merges):
        counts = {}
        for p in zip(ids, ids[1:]):
            counts[p] = counts.get(p, 0) + 1      # dict 的插入顺序 = 首次出现的顺序
        if not counts:
            break
        pair = max(counts, key=counts.get)       # 并列时 max 取最先插入的，即最早出现的
        if counts[pair] < 2:
            break
        ids = _merge(ids, pair, 256 + len(merges))
        merges.append(pair)
    return merges


def encode(text, merges):
    rank = {p: i for i, p in enumerate(merges)}
    ids = list(text.encode("utf-8"))
    while len(ids) >= 2:
        pair = min(zip(ids, ids[1:]), key=lambda p: rank.get(p, float("inf")))
        if pair not in rank:                     # 没有可合并的对了
            break
        ids = _merge(ids, pair, 256 + rank[pair])
    return ids


def decode(ids, merges):
    vocab = {i: bytes([i]) for i in range(256)}
    for i, (a, b) in enumerate(merges):
        vocab[256 + i] = vocab[a] + vocab[b]
    return b"".join(vocab[i] for i in ids).decode("utf-8", errors="replace")

import zlib
from collections import defaultdict
from itertools import combinations

def minhash_signature(shingles, a, b, p):
    xs = [zlib.crc32(s.encode()) for s in shingles]
    return [min((ai * x + bi) % p for x in xs) for ai, bi in zip(a, b)]

def lsh_candidates(signatures, bands):
    if not signatures:
        return set()
    r = len(signatures[0]) // bands
    buckets = defaultdict(list)                 # (段号, 段内容) -> 文档号列表
    for doc_id, sig in enumerate(signatures):
        for k in range(bands):
            buckets[(k, tuple(sig[k * r:(k + 1) * r]))].append(doc_id)
    pairs = set()
    for ids in buckets.values():
        pairs.update(combinations(ids, 2))      # ids 按文档号递增，保证 i < j
    return pairs

def _ngrams(text, n):
    words = text.lower().split()
    return [tuple(words[i:i + n]) for i in range(len(words) - n + 1)]

def build_ngram_index(train_docs, n):
    index = set()
    for doc in train_docs:
        index.update(_ngrams(doc, n))
    return index

def contamination_ratio(example, index, n):
    grams = _ngrams(example, n)
    if not grams:                       # 不足 n 个词
        return 0.0
    return sum(g in index for g in grams) / len(grams)

**问题**：第 5～10 行用 `if / elif` 让每个阶段**只切自己新增的那一项**：stage 2 只切梯度、不切优化器状态，stage 3 只切参数、梯度和优化器状态都不切。于是 ZeRO-2、ZeRO-3 都约为 105.2 GB，比 ZeRO-1 还大。

**修正**：ZeRO 的阶段是累加的，高阶段包含低阶段的全部切分，改成三个独立的 `if stage >= k`：

```python
if stage >= 1:
    optim /= n_gpu
if stage >= 2:
    grad /= n_gpu
if stage >= 3:
    weight /= n_gpu
```

import math
import torch
import torch.nn as nn

class LoRALinear(nn.Module):
    def __init__(self, base: nn.Linear, r: int = 8, alpha: float = 16):
        super().__init__()
        self.base, self.scaling, self.merged = base, alpha / r, False
        for p in self.base.parameters():
            p.requires_grad_(False)                                   # 冻结原层
        self.A = nn.Parameter(torch.empty(r, base.in_features))       # (r, k) 降维
        self.B = nn.Parameter(torch.zeros(base.out_features, r))      # (d, r) 升维，零初始化
        nn.init.kaiming_uniform_(self.A, a=math.sqrt(5))

    def forward(self, x):
        y = self.base(x)
        if not self.merged:
            y = y + (x @ self.A.T @ self.B.T) * self.scaling          # 不构造 d×k 的 ΔW
        return y

    @torch.no_grad()
    def merge(self):
        if not self.merged:
            self.base.weight += self.scaling * self.B @ self.A
            self.merged = True

    @torch.no_grad()
    def unmerge(self):
        if self.merged:
            self.base.weight -= self.scaling * self.B @ self.A
            self.merged = False

from collections import Counter


def attribute(cases, k):
    counts = Counter()
    for case in cases:
        gold, ranked = set(case["gold"]), list(case["ranked"])
        if case["answer_ok"]:
            label = "ok"
        elif not gold:
            label = "missing"
        elif not gold & set(ranked):
            label = "not_retrieved"
        elif not gold & set(ranked[:k]):
            label = "ranked_out"
        else:
            label = "not_used"
        counts[label] += 1
    return counts

def _split_keep(text, sep):
    """按 sep 拆分，分隔符留在前一段末尾，保证拼接后与原文一致"""
    if sep == "":
        return list(text)
    parts = text.split(sep)
    pieces = [p + sep for p in parts[:-1]] + [parts[-1]]
    return [p for p in pieces if p]


def _atoms(text, size, seps):
    """把 text 拆成长度都不超过 size 的原子片段"""
    if len(text) <= size:
        return [text] if text else []
    sep = next(s for s in seps if s == "" or s in text)   # 出现的最高级分隔符
    rest = seps[seps.index(sep) + 1:]
    out = []
    for piece in _split_keep(text, sep):
        out += [piece] if len(piece) <= size else _atoms(piece, size, rest)
    return out


def recursive_chunk(text, size, seps=("\n\n", "\n", "。", "，", "")):
    chunks, cur = [], ""
    for piece in _atoms(text, size, list(seps)):
        if cur and len(cur) + len(piece) > size:
            chunks.append(cur)
            cur = ""
        cur += piece
    if cur:
        chunks.append(cur)
    return chunks

import math
from collections import Counter, defaultdict


class BM25:
    def __init__(self, docs, k1=1.2, b=0.75):
        self.k1, self.b = k1, b
        self.lens = [len(d) for d in docs]
        self.avgdl = sum(self.lens) / len(docs) if docs else 0.0
        self.index = defaultdict(list)                  # 词 -> [(文档编号, 词频)]
        for i, doc in enumerate(docs):
            for t, f in Counter(doc).items():
                self.index[t].append((i, f))
        n_docs = len(docs)
        self.idf = {t: math.log(1 + (n_docs - len(p) + 0.5) / (len(p) + 0.5))
                    for t, p in self.index.items()}

    def search(self, query, k):
        scores = defaultdict(float)
        for t in set(query):
            for i, f in self.index.get(t, []):
                K = self.k1 * (1 - self.b + self.b * self.lens[i] / self.avgdl)
                scores[i] += self.idf[t] * f * (self.k1 + 1) / (f + K)
        return sorted(scores.items(), key=lambda x: (-x[1], x[0]))[:k]

def clean_filter(raw, schema):
    out = {}
    for key, val in raw.items():
        rule = schema.get(key)
        if rule is None:                      # 白名单之外的字段
            continue
        if rule["type"] == "enum":
            if isinstance(val, str) and val in rule["values"]:
                out[key] = val
        elif rule["type"] == "int":
            if (isinstance(val, int) and not isinstance(val, bool)
                    and rule["min"] <= val <= rule["max"]):
                out[key] = val
    return out

import hashlib

def h(text):
    return hashlib.sha256(text.encode()).hexdigest()[:12]

def plan_sync(index, new_docs):
    to_add, to_delete = [], []
    for doc_id in set(index) | set(new_docs):
        old = index.get(doc_id, set())
        new = {h(t) for t in new_docs.get(doc_id, [])}
        to_add += [(doc_id, x) for x in new - old]
        to_delete += [(doc_id, x) for x in old - new]
    return sorted(to_add), sorted(to_delete)

import json


def run_agent(llm, tools, task, max_steps=8, max_tokens=None, max_repeat=3):
    messages = [{"role": "user", "content": task}]
    used, recent = 0, []                      # recent：已执行调用的签名
    for step in range(1, max_steps + 1):
        reply = llm(messages)
        used += reply.get("tokens", 0)
        if "final" in reply:
            return {"status": "done", "answer": reply["final"], "steps": step}
        if max_tokens is not None and used > max_tokens:
            return {"status": "budget", "answer": None, "steps": step}
        name, args = reply.get("tool"), reply.get("args") or {}
        sig = (name, json.dumps(args, sort_keys=True, ensure_ascii=False))
        k = max_repeat - 1
        if len(recent) >= k and all(s == sig for s in recent[-k:]):
            return {"status": "repeat", "answer": None, "steps": step}
        recent.append(sig)
        messages.append({"role": "assistant", "tool": name, "args": args})
        messages.append({"role": "tool", "content": execute(tools, name, args)})
    return {"status": "max_steps", "answer": None, "steps": max_steps}


def execute(tools, name, args):
    spec = tools.get(name)
    if spec is None:
        return f"错误：未知工具 {name}"
    missing = [p for p in spec.get("required", []) if p not in args]
    if missing:
        return "错误：缺少参数 " + ", ".join(missing)
    try:
        return str(spec["fn"](**args))
    except Exception as e:                    # 工具异常回填给模型，而不是让循环崩溃
        return f"错误：{type(e).__name__}: {e}"

import re

def normalize(ans):
    s = ans.strip().rstrip("。.").replace(",", "").replace("，", "")
    try:
        if s.endswith("%"):
            v = float(s[:-1]) / 100
        elif re.fullmatch(r"-?\d+(\.\d+)?/\d+(\.\d+)?", s):
            a, b = s.split("/")
            v = float(a) / float(b)
        else:
            v = float(s)
    except (ValueError, ZeroDivisionError):
        return s                       # 不是数值，保持原样
    return str(int(v)) if v.is_integer() else str(v)

def vote(outputs):
    answers = []
    for out in outputs:
        found = re.findall(r"答案[:：]\s*(.+)", out)
        if found:
            answers.append(normalize(found[-1]))
    if not answers:
        return None, 0.0
    # 票数多者优先；平票时，首次出现位置越靠前越优先
    best = max(answers, key=lambda a: (answers.count(a), -answers.index(a)))
    return best, answers.count(best) / len(outputs)

import json

def extract_json(text):
    start = text.find("{")
    while start != -1:
        depth, in_str, esc = 0, False, False
        for i in range(start, len(text)):
            c = text[i]
            if in_str:                       # 字符串内部：只关心转义和结束引号
                if esc:
                    esc = False
                elif c == "\\":
                    esc = True
                elif c == '"':
                    in_str = False
            elif c == '"':
                in_str = True
            elif c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:               # 找到配对的右括号
                    try:
                        obj = json.loads(text[start:i + 1])
                        if isinstance(obj, dict):
                            return obj
                    except json.JSONDecodeError:
                        pass
                    break
        start = text.find("{", start + 1)    # 从下一个左括号继续尝试
    raise ValueError("没有找到合法的 JSON 对象")

def schedule(tasks):
    for t, deps in tasks.items():
        for d in deps:
            if d not in tasks:
                raise ValueError(f"任务 {t} 依赖不存在的任务 {d}")
    indeg = {t: len(set(deps)) for t, deps in tasks.items()}
    children = {t: [] for t in tasks}
    for t, deps in tasks.items():
        for d in set(deps):
            children[d].append(t)
    wave = sorted(t for t, k in indeg.items() if k == 0)
    waves, done = [], 0
    while wave:
        waves.append(wave)
        done += len(wave)
        nxt = []
        for t in wave:
            for c in children[t]:
                indeg[c] -= 1
                if indeg[c] == 0:
                    nxt.append(c)
        wave = sorted(nxt)
    if done != len(tasks):
        raise ValueError("依赖关系存在环，无法调度")
    return waves

import json


def detect_oscillation(steps, max_period=3, repeats=3):
    sig = [(s["tool"], json.dumps(s.get("args", {}), sort_keys=True, ensure_ascii=False),
            s.get("obs", "")) for s in steps]
    n = len(sig)
    for p in range(1, max_period + 1):
        m = p * repeats
        if m > n:
            break                      # 周期更大时需要的步数更多，也不可能满足
        if all(sig[i] == sig[i + p] for i in range(n - m, n - p)):
            start = n - m
            while start > 0 and sig[start - 1] == sig[start - 1 + p]:
                start -= 1             # 向前延伸，找到震荡真正开始的位置
            return p, start
    return None

def validate(schema, value, path="$"):
    types = schema.get("type")
    types = [types] if isinstance(types, str) else (types or [])

    def is_type(t, v):
        if t == "integer":
            return isinstance(v, int) and not isinstance(v, bool)
        if t == "number":
            return isinstance(v, (int, float)) and not isinstance(v, bool)
        return isinstance(v, {"string": str, "boolean": bool, "null": type(None),
                              "object": dict, "array": list}[t])

    if types and not any(is_type(t, value) for t in types):
        return [(path, "type")]
    if "enum" in schema and value not in schema["enum"]:
        return [(path, "enum")]
    errs = []
    if isinstance(value, dict):
        props = schema.get("properties", {})
        errs += [(f"{path}.{k}", "required") for k in schema.get("required", [])
                 if k not in value]
        if schema.get("additionalProperties") is False:
            errs += [(f"{path}.{k}", "additional") for k in value if k not in props]
        for k, v in value.items():
            if k in props:
                errs += validate(props[k], v, f"{path}.{k}")
    elif isinstance(value, list) and "items" in schema:
        for i, v in enumerate(value):
            errs += validate(schema["items"], v, f"{path}[{i}]")
    return errs

def check_protocol(messages):
    errs, pending = [], set()
    for i, m in enumerate(messages):
        if m["role"] == "tool":
            if m.get("tool_call_id") not in pending:
                errs.append((i, "orphan"))
            pending.discard(m.get("tool_call_id"))
            continue
        if pending:
            errs.append((i, "unanswered"))
            pending = set()
        for c in m.get("tool_calls") or []:
            if c["id"] in pending:
                errs.append((i, "duplicate_id"))
            pending.add(c["id"])
    if pending:
        errs.append((len(messages), "unanswered"))
    return errs

import json
import time


class ToolCache:
    def __init__(self, specs, clock=time.monotonic):
        self.specs, self.clock = specs, clock
        self.store = {}                    # (user, tool, 规范化参数) -> (结果, 写入时刻, 资源)

    def call(self, user, tool, args, fn):
        spec = self.specs[tool]
        res = args.get(spec["key"]) if "key" in spec else None
        if spec["mode"] == "write":
            try:
                return fn(**args), False
            finally:                       # 无论成功还是抛异常，都先失效相关缓存
                self._invalidate(res)
        k = (user, tool, json.dumps(args, sort_keys=True, ensure_ascii=False))
        hit = self.store.get(k)
        if hit is not None and self.clock() - hit[1] < spec["ttl"]:
            return hit[0], True
        out = fn(**args)                   # 读失败时异常直接抛出，不写缓存
        self.store[k] = (out, self.clock(), res)
        return out, False

    def _invalidate(self, res):
        if res is None:                    # 不知道写了什么：保守地清空全部
            self.store.clear()
        else:
            self.store = {k: v for k, v in self.store.items() if v[2] != res}

TERMINAL = {"completed", "failed", "canceled", "rejected"}
NEXT = {
    "submitted": {"working", "rejected", "canceled", "failed"},
    "working": {"working", "input-required", "auth-required",
                "completed", "failed", "canceled"},
    "input-required": {"working", "canceled", "failed"},
    "auth-required": {"working", "canceled", "failed"},
}

def first_illegal(states):
    if not states or states[0] != "submitted":
        return 0
    for i in range(1, len(states)):
        prev, cur = states[i - 1], states[i]
        if prev in TERMINAL or cur not in NEXT.get(prev, set()):
            return i
    return -1

import re

NAME_RE = re.compile(r"[a-z0-9]+(-[a-z0-9]+)*")


def check_skill(dirname, text):
    lines = text.split("\n")
    if lines[0].strip() != "---":
        return ["no_frontmatter"]
    end = next((i for i in range(1, len(lines)) if lines[i].strip() == "---"), None)
    if end is None:
        return ["no_frontmatter"]
    fm = {}
    for line in lines[1:end]:
        if not line.strip() or line[0] in " \t" or ":" not in line:
            continue                       # 跳过空行与缩进的嵌套内容
        key, val = line.split(":", 1)
        val = val.strip()
        if len(val) >= 2 and val[0] == val[-1] and val[0] in "'\"":
            val = val[1:-1]
        fm[key.strip()] = val
    errs = []
    name = fm.get("name", "")
    if not name:
        errs.append("name_missing")
    else:
        if len(name) > 64 or not NAME_RE.fullmatch(name):
            errs.append("name_invalid")
        if name != dirname:
            errs.append("name_mismatch")
    desc = fm.get("description", "")
    if not desc:
        errs.append("description_missing")
    elif len(desc) > 1024:
        errs.append("description_too_long")
    if "compatibility" in fm and not 1 <= len(fm["compatibility"]) <= 500:
        errs.append("compatibility_invalid")
    return errs

def _covers(lo, hi, x):
    return lo <= x and (hi is None or x < hi)

def assert_fact(records, value, valid_from, now):
    active = [r for r in records if r["expired_at"] is None]
    for r in active:
        if _covers(r["valid_from"], r["valid_to"], valid_from):
            if r["value"] == value:
                return
            r["expired_at"] = now
            if r["valid_from"] < valid_from:
                records.append({"value": r["value"], "valid_from": r["valid_from"],
                                "valid_to": valid_from, "recorded_at": now,
                                "expired_at": None})
    later = [r["valid_from"] for r in active if r["valid_from"] > valid_from]
    records.append({"value": value, "valid_from": valid_from,
                    "valid_to": min(later) if later else None,
                    "recorded_at": now, "expired_at": None})

def query(records, t, tx):
    hits = [r for r in records
            if _covers(r["recorded_at"], r["expired_at"], tx)
            and _covers(r["valid_from"], r["valid_to"], t)]
    return [r["value"] for r in sorted(hits, key=lambda r: r["valid_from"])]

from collections import defaultdict, deque

def cascade_delete(records, user):
    children = defaultdict(list)                 # 来源 id -> 由它派生的记录
    for rid, rec in records.items():
        for src in rec["sources"]:
            children[src].append(rid)
    todo = deque(rid for rid, rec in records.items() if rec["owner"] == user)
    doomed = set(todo)
    while todo:
        for child in children[todo.popleft()]:
            if child not in doomed:
                doomed.add(child)
                todo.append(child)
    return sorted(doomed)

class InvalidUpdateError(Exception):
    pass

def apply_superstep(state, updates, reducers):
    writes = {}
    for upd in updates:
        for key, value in upd.items():
            if key not in reducers:
                raise KeyError(key)
            writes.setdefault(key, []).append(value)
    new = dict(state)
    for key, values in writes.items():
        reducer = reducers[key]
        if reducer is None:
            if len(values) > 1:
                raise InvalidUpdateError(f"At key {key!r}: can receive only one value per step")
            new[key] = values[0]
        else:
            acc = new[key]
            for v in values:
                acc = reducer(acc, v)
            new[key] = acc
    return new

**问题**：打款（第 24 行的 `PAID.append`）写在 `interrupt()` 之前，造成两个后果：

1. 第一次执行时还没审批就已经打款，驳回也来不及了；
2. 恢复时节点从头重跑，打款代码再执行一次，批准后一共打了两次款。

**修正**：先等审批结果，批准后才执行副作用：

```python
def refund_node(rt, state):
    ok = rt.interrupt({"question": "确认退款？", "amount": state["amount"]})
    if ok != "approve":
        return {"status": "rejected"}
    PAID.append(state["amount"])                # 审批通过后才打款
    return {"status": "refunded"}
```

def resolve(deps, fails, partial):
    for t, ups in deps.items():
        for u in ups:
            if u not in deps:
                raise ValueError(f"{t} 依赖了不存在的任务 {u}")
    indeg = {t: len(set(ups)) for t, ups in deps.items()}
    children = {t: [] for t in deps}
    for t, ups in deps.items():
        for u in set(ups):
            children[u].append(t)
    ready = [t for t, k in indeg.items() if k == 0]
    status = {}
    while ready:
        t = ready.pop()
        if t not in partial and any(status[u] != "ok" for u in deps[t]):
            status[t] = "skipped"
        else:
            status[t] = "failed" if t in fails else "ok"
        for c in children[t]:
            indeg[c] -= 1
            if indeg[c] == 0:
                ready.append(c)
    if len(status) != len(deps):
        raise ValueError("任务图有环")
    return status

import threading


class TaskBoard:
    def __init__(self, tasks):
        for t, deps in tasks.items():
            for d in deps:
                if d not in tasks:
                    raise ValueError(f"未知依赖 {d}")
        self.deps = {t: set(ds) for t, ds in tasks.items()}
        indeg = {t: len(ds) for t, ds in self.deps.items()}
        ready, seen = [t for t, k in indeg.items() if k == 0], 0
        while ready:                               # Kahn 算法检查依赖是否成环
            t = ready.pop()
            seen += 1
            for u, ds in self.deps.items():
                if t in ds:
                    indeg[u] -= 1
                    if indeg[u] == 0:
                        ready.append(u)
        if seen != len(tasks):
            raise ValueError("依赖成环")
        self.state = {t: "pending" for t in tasks}
        self.owner = {}
        self.lock = threading.Lock()

    def _ready(self, t):
        return self.state[t] == "pending" and all(self.state[d] == "completed" for d in self.deps[t])

    def status(self, t):
        return "blocked" if self.state[t] == "pending" and not self._ready(t) else self.state[t]

    def claim(self, agent):
        with self.lock:                            # 认领是「检查 + 修改」，必须原子
            if any(s == "in_progress" and self.owner[t] == agent for t, s in self.state.items()):
                return None
            for t in sorted(self.state):
                if self._ready(t):
                    self.state[t], self.owner[t] = "in_progress", agent
                    return t
            return None

    def complete(self, agent, t):
        with self.lock:
            if self.state[t] != "in_progress" or self.owner[t] != agent:
                raise PermissionError(f"{agent} 不能完成 {t}")
            before = {u for u in self.state if self._ready(u)}
            self.state[t] = "completed"
            return sorted(u for u in self.state if self._ready(u) and u not in before)

import re

def _match(pattern, cmd):
    regex = ".*".join(re.escape(part) for part in pattern.split("*"))
    if re.fullmatch(regex, cmd, flags=re.S):
        return True
    return pattern.endswith(" *") and cmd == pattern[:-2]

def decide(rules, command):
    segs = [s.strip() for s in re.split(r"&&|\|\||;|\|", command)]
    segs = [s for s in segs if s]
    if not segs:
        return "ask"
    for effect in ("deny", "ask"):
        if any(_match(p, s) for s in segs for p in rules.get(effect, [])):
            return effect
    allow = rules.get("allow", [])
    if all(any(_match(p, s) for p in allow) for s in segs):
        return "allow"
    return "ask"

def compact(text, max_lines=6):
    if not text.strip():
        return "（命令执行成功，没有输出）"
    rows = []                                  # [内容, 连续出现次数]
    for line in text.splitlines():
        if rows and rows[-1][0] == line:
            rows[-1][1] += 1
        else:
            rows.append([line, 1])
    shown = [s + (f"  [×{n}]" if n > 1 else "") for s, n in rows]
    if len(rows) <= max_lines:
        return "\n".join(shown)
    h = max_lines // 2
    t = max_lines - h
    omitted = sum(n for _, n in rows[h:len(rows) - t])
    return "\n".join(shown[:h] + [f"…省略 {omitted} 行…"] + shown[len(rows) - t:])

class EditError(Exception):
    pass

def _ws(line):
    return " ".join(line.split())

def _indent(line):
    return line[:len(line) - len(line.lstrip())]

def apply_edit(text, search, replace):
    if not search.strip():
        raise EditError("SEARCH 为空，请带上要修改的原文")
    lines, s, r = text.splitlines(), search.splitlines(), replace.splitlines()
    n = len(s)
    for key in (lambda x: x, _ws):
        want = [key(x) for x in s]
        hits = [i for i in range(len(lines) - n + 1)
                if [key(x) for x in lines[i:i + n]] == want]
        if len(hits) > 1:
            where = "、".join(str(i + 1) for i in hits)
            raise EditError(f"SEARCH 在第 {where} 行匹配到 {len(hits)} 处，请补充上下文使其唯一")
        if len(hits) == 1:
            i = hits[0]
            pad, spad = _indent(lines[i]), _indent(s[0])
            fixed = [pad + x[len(spad):] if x.startswith(spad) else x for x in r]
            return "\n".join(lines[:i] + fixed + lines[i + n:]) + "\n"
    raise EditError("SEARCH 找不到，请重新读取文件后从原文逐字复制")

import re

NUM = re.compile(r"\d+(?:\.\d+)?")

def check(claim, cited, sources):
    if not cited:
        return "无引用"
    need = set(NUM.findall(claim))
    have = set()
    for k in cited:
        have |= set(NUM.findall(sources.get(k, "")))
    if need <= have:
        return "通过"
    for k in sorted(sources):
        if k not in cited and need <= set(NUM.findall(sources[k])):
            return f"引错来源，应引 [{k}]"
    return "数字不符"

from html.parser import HTMLParser

VOID = {"input", "img", "br", "hr", "meta", "link"}
INTERACTIVE = {"a", "button", "input", "select", "textarea"}


class _Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hidden = [False]     # 栈：当前所在子树是否被隐藏
        self.items = []           # [标签, 属性, 内部文字]
        self.open = []            # 尚未闭合、正在收集文字的交互元素

    def handle_starttag(self, tag, attrs):
        a = {k: v or "" for k, v in attrs}
        style = a.get("style", "").replace(" ", "").lower()
        hide = (self.hidden[-1] or tag in ("script", "style") or "hidden" in a
                or "display:none" in style
                or (tag == "input" and a.get("type", "").lower() == "hidden"))
        if tag in INTERACTIVE and not hide:
            item = [tag, a, ""]
            self.items.append(item)
            if tag not in VOID:
                self.open.append(item)
        if tag not in VOID:
            self.hidden.append(hide)

    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if len(self.hidden) > 1:
            self.hidden.pop()
        if self.open and self.open[-1][0] == tag:
            self.open.pop()

    def handle_data(self, data):
        if self.open and not self.hidden[-1]:
            self.open[-1][2] += data.strip()


def simplify(html):
    p = _Parser()
    p.feed(html)
    p.close()
    out = []
    for i, (tag, a, text) in enumerate(p.items, 1):
        name = a.get("aria-label") or text or a.get("placeholder") or ""
        out.append(f'[{i}] {tag} "{name}"')
    return out

**问题**：第 2～3 行先算 $\hat p=c/n$，再代入 $1-(1-\hat p)^k$。这是「有放回抽样」的公式，而且 $1-(1-p)^k$ 是 $p$ 的凹函数，由 Jensen 不等式，代入估计值得到的结果**系统性偏低**，不是无偏估计。$n=5,c=1,k=5$ 时，5 次结果里已经有 1 次成功，「从这 5 次里抽 5 次」必然包含它，真值是 1，函数却给出 $1-0.8^5\approx0.672$。

**修正**：用 Codex 论文的无偏估计 $1-\binom{n-c}{k}/\binom{n}{k}$，即「从 $n$ 个结果里无放回抽 $k$ 个，不全是失败」的概率。为避免组合数过大，改写成连乘：
$$\frac{\binom{n-c}{k}}{\binom{n}{k}}=\prod_{i=n-c+1}^{n}\left(1-\frac{k}{i}\right)$$

```python
import numpy as np

def pass_at_k(n, c, k):
    if n - c < k:
        return 1.0
    return 1.0 - float(np.prod(1.0 - k / np.arange(n - c + 1, n + 1)))
```

from collections import Counter

def _norm(v):
    if isinstance(v, str):
        return v.strip().lower()
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return float(v)
    return v

def _canon(call):
    name, args = call
    return (name, tuple(sorted((k, _norm(v)) for k, v in args.items())))

def traj_metrics(pred, ref, deps):
    hit = sum((Counter(map(_canon, pred)) & Counter(map(_canon, ref))).values())
    p = hit / len(pred) if pred else 0.0
    r = hit / len(ref) if ref else 0.0
    f1 = 2 * p * r / (p + r) if p + r else 0.0
    first = {}
    for i, (name, _) in enumerate(pred):
        first.setdefault(name, i)          # 只记首次出现的位置
    checked = ok = 0
    for a, b in deps:
        if b not in first:
            continue
        checked += 1
        ok += a in first and first[a] < first[b]
    return {"p": p, "r": r, "f1": f1, "dep": ok / checked if checked else 1.0}

import random
import time

class RetryableError(Exception):
    def __init__(self, msg="", retry_after=None):
        super().__init__(msg)
        self.retry_after = retry_after

def retry_call(fn, *, max_attempts=4, base=0.5, cap=8.0,
               sleep=time.sleep, rand=random.uniform):
    for attempt in range(max_attempts):
        try:
            return fn()
        except RetryableError as e:
            if attempt == max_attempts - 1:
                raise                                # 次数用尽，抛出最后一次的错误
            wait = rand(0, min(cap, base * 2 ** attempt))
            if e.retry_after is not None:
                wait = max(wait, e.retry_after)      # 至少等服务端要求的时长
            sleep(wait)

import hashlib
import json

class Conflict(Exception):
    pass

class IdempotencyStore:
    def __init__(self, ttl, clock):
        self.ttl, self.clock, self.records = ttl, clock, {}

    @staticmethod
    def _fingerprint(body):
        return hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()

    def execute(self, key, body, handler):
        fp, now = self._fingerprint(body), self.clock()
        rec = self.records.get(key)
        if rec is not None and now < rec["expire"]:
            if rec["fp"] != fp:
                raise Conflict(f"键 {key} 已用于另一个请求")
            return rec["resp"]                 # 重放首次的响应
        resp = handler(body)                   # 抛异常时不写记录
        self.records[key] = {"fp": fp, "resp": resp, "expire": now + self.ttl}
        return resp

class TokenBucket:
    def __init__(self, rate, capacity, clock):
        self.rate, self.capacity, self.clock = rate, capacity, clock
        self.tokens, self.last = float(capacity), clock()

    def _refill(self):
        now = self.clock()
        self.tokens = min(self.capacity, self.tokens + self.rate * (now - self.last))
        self.last = now

    def try_acquire(self, n=1):
        if n > self.capacity:
            return False, float("inf")      # 永远攒不够
        self._refill()
        if self.tokens >= n:
            self.tokens -= n
            return True, 0.0
        return False, (n - self.tokens) / self.rate

    def refund(self, n):
        self._refill()
        self.tokens = min(self.capacity, self.tokens + n)

import json

class ReplayMismatch(Exception):
    pass

class ToolRecorder:
    def __init__(self, mode, tape=None):
        assert mode in ("record", "replay")
        self.mode = mode
        self.tape = tape if tape is not None else []
        self.pos = 0

    @staticmethod
    def _key(name, args):
        return name, json.dumps(args, sort_keys=True)

    def call(self, name, fn, **args):
        if self.mode == "record":
            result = fn(**args)
            self.tape.append({"name": name, "args": args, "result": result})
            return result
        if self.pos >= len(self.tape):
            raise ReplayMismatch(f"磁带已用完，多出的调用：{name}")
        entry = self.tape[self.pos]
        if self._key(entry["name"], entry["args"]) != self._key(name, args):
            raise ReplayMismatch(f"第 {self.pos} 次调用与录制不一致：{name} {args}")
        self.pos += 1
        return entry["result"]

def evaluate(records, tau, c_small=0.1, c_large=1.0):
    ok = cost = 0.0
    for score, small_ok, large_ok in records:
        if score < tau:
            ok, cost = ok + small_ok, cost + c_small
        else:
            ok, cost = ok + large_ok, cost + c_large
    return ok / len(records), cost / len(records)

def pick_threshold(records, taus, max_drop):
    if not records:
        raise ValueError("records 不能为空")
    floor = sum(r[2] for r in records) / len(records) - max_drop   # 质量下限
    best = None
    for tau in sorted(taus):                    # 从小到大，成本相同时保留较小的 tau
        q, c = evaluate(records, tau)
        if q >= floor - 1e-12 and (best is None or c < best[2] - 1e-12):
            best = (tau, q, c)
    return best

import unicodedata

BIDI = set(range(0x202A, 0x202F)) | set(range(0x2066, 0x206A))


def scan_hidden(text):
    text = unicodedata.normalize("NFKC", text)
    kept, tags, removed, bidi = [], [], 0, False
    for ch in text:
        cp = ord(ch)
        if unicodedata.category(ch) == "Cf":       # 零宽、双向控制、标签字符等
            removed += 1
            if 0xE0020 <= cp <= 0xE007E:           # 标签字符 = ASCII + 0xE0000
                tags.append(chr(cp - 0xE0000))
            if cp in BIDI:
                bidi = True
        else:
            kept.append(ch)
    return "".join(kept), {"removed": removed, "tags": "".join(tags), "bidi": bidi}

