from urllib.parse import parse_qsl, urlsplit

B64 = re.compile(r"[A-Za-z0-9+/=_-]{24,}")


def check_url(url, allowed):
    try:
        u = urlsplit(url)
        host = (u.hostname or "").rstrip(".").lower()
    except ValueError:
        return "无法解析"
    if u.scheme not in ("http", "https"):
        return f"协议 {u.scheme} 不允许"
    if not any(host == d or host.endswith("." + d) for d in allowed):
        return f"域名 {host} 不在白名单"
    for k, v in parse_qsl(u.query, keep_blank_values=True):
        if len(v) > 48 or B64.fullmatch(v) or "://" in v:
            return f"参数 {k} 可疑"
    return None

import hashlib
import json


def fingerprint(tool):
    canon = json.dumps({k: tool.get(k) for k in ("name", "description", "inputSchema")},
                       sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(canon.encode("utf-8")).hexdigest()


class Pinner:
    def __init__(self):
        self.pins = {}        # (server, 工具名) -> 审核时钉住的指纹
        self.owner = {}       # 工具名 -> 最早注册它的 server

    def sync(self, server, tools):
        out = []
        for t in tools:
            name, fp = t["name"], fingerprint(t)
            owner = self.owner.setdefault(name, server)
            if owner != server:
                out.append((name, "shadow"))            # 与其他 server 的工具同名
            elif (server, name) not in self.pins:
                self.pins[(server, name)] = fp
                out.append((name, "pinned"))
            elif self.pins[(server, name)] == fp:
                out.append((name, "ok"))
            else:
                out.append((name, "changed"))           # 不更新指纹，等待重审
        return out

class Labeled:
    def __init__(self, value, sources=("user",), readers=None):
        self.value = value
        self.sources = frozenset(sources)
        self.readers = None if readers is None else frozenset(readers)


def concat(*parts):
    value = "".join(p.value for p in parts)
    sources = frozenset().union(*(p.sources for p in parts))     # 来源取并集
    readers = None                                               # None 表示公开
    for p in parts:
        if p.readers is not None:                                # 公开的部分不加限制
            readers = p.readers if readers is None else readers & p.readers
    return Labeled(value, sources, readers)


