from collections import deque


class TokenRateLimiter:
    def __init__(self, limit, window=60.0):
        if limit <= 0 or window <= 0:
            raise ValueError("limit 与 window 必须为正")
        self.limit, self.window = limit, window
        self.q = deque()               # (放行时间, token 数)，时间单调不减
        self.total = 0                 # 窗口内的 token 总数

    def _evict(self, now):
        while self.q and self.q[0][0] <= now - self.window:
            self.total -= self.q.popleft()[1]

    def used(self, now):
        self._evict(now)
        return self.total

    def try_acquire(self, tokens, now):
        if tokens <= 0:
            raise ValueError("tokens 必须为正")
        self._evict(now)
        if self.total + tokens > self.limit:
            return False               # 拒绝的请求不占额度
        self.q.append((now, tokens))
        self.total += tokens
        return True

def close_json(prefix):
    stack = []                     # 尚未闭合的容器，存放对应的右括号
    in_str = esc = False
    for ch in prefix:
        if in_str:
            if esc:
                esc = False        # 转义序列的第二个字符，原样跳过
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch in "[{":
            stack.append("]" if ch == "[" else "}")
        elif ch in "]}":
            stack.pop()
    return ('"' if in_str else "") + "".join(reversed(stack))

import heapq
from collections import Counter


class _Entry:
    __slots__ = ("cnt", "word")

    def __init__(self, cnt, word):
        self.cnt, self.word = cnt, word

    def __lt__(self, other):           # 「更差」的更小：次数少；次数相同则字典序大
        if self.cnt != other.cnt:
            return self.cnt < other.cnt
        return self.word > other.word


def top_k_frequent(words, k):
    if k <= 0:
        return []
    heap = []                          # 小顶堆，堆顶是当前入选者中最差的一个
    for word, cnt in Counter(words).items():
        e = _Entry(cnt, word)
        if len(heap) < k:
            heapq.heappush(heap, e)
        elif heap[0] < e:              # 新词比堆顶好，替换堆顶
            heapq.heapreplace(heap, e)
    out = []
    while heap:
        out.append(heapq.heappop(heap).word)
    return out[::-1]                   # 弹出顺序是从差到好，反转

class ListNode:
    def __init__(self, val=0, next=None):
        self.val, self.next = val, next


def reverse_k_group(head, k):
    dummy = ListNode(0, head)
    tail = dummy                           # 已处理部分的尾节点
    while True:
        node = tail                        # 先确认后面还有 k 个节点
        for _ in range(k):
            node = node.next
            if node is None:
                return dummy.next          # 不足 k 个：保持原样
        first, nxt = tail.next, node.next  # 本组首节点、下一组首节点
        prev, cur = nxt, first             # 组内原地反转，反转后的尾直接接上下一组
        while cur is not nxt:
            cur.next, prev, cur = prev, cur, cur.next
        tail.next = prev                   # prev 是本组反转后的头
        tail = first                       # 原来的首节点成了本组的尾

class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right


def lowest_common_ancestor(root, p, q):
    if root is None or root is p or root is q:
        return root                        # 找到 p 或 q（或走到空）就向上报告
    left = lowest_common_ancestor(root.left, p, q)
    right = lowest_common_ancestor(root.right, p, q)
    if left is not None and right is not None:
        return root                        # p、q 分居两侧：root 就是分叉点
    return left if left is not None else right

**问题**：第 9～12 行只比较了节点与它的**直接孩子**。二叉搜索树的约束是对整棵子树的：左子树中所有节点都要小于根。例如根为 5、左孩子为 3、3 的右孩子为 6：每对父子关系都合法，但 6 出现在 5 的左子树里，原函数却返回 `True`。

**修正**：向下递归时传递取值范围 `(lo, hi)`，每个节点都必须严格落在祖先们给出的上下界之内：

```python
def is_bst(node, lo=float("-inf"), hi=float("inf")):
    if node is None:
        return True
    if not lo < node.val < hi:
        return False
    return is_bst(node.left, lo, node.val) and is_bst(node.right, node.val, hi)
```

from collections import deque


def num_islands(grid):
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    seen = [[False] * n for _ in range(m)]
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] != "1" or seen[i][j]:
                continue
            count += 1                     # 发现一个新岛屿，用 BFS 把它整个标记掉
            seen[i][j] = True
            queue = deque([(i, j)])
            while queue:
                x, y = queue.popleft()
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == "1" and not seen[nx][ny]:
                        seen[nx][ny] = True        # 入队时就标记，避免重复入队
                        queue.append((nx, ny))
    return count

from collections import deque


def earliest_finish(tasks):
    indeg = {t: 0 for t in tasks}
    children = {t: [] for t in tasks}
    for t, (_, deps) in tasks.items():
        for d in set(deps):                # 重复的依赖只算一次
            indeg[t] += 1
            children[d].append(t)
    start = {t: 0 for t in tasks}          # 最早开始时间
    prev = {t: None for t in tasks}        # 决定最早开始时间的那个前置任务
    finish = {}
    queue = deque(t for t in tasks if indeg[t] == 0)
    while queue:                           # 按拓扑序推进
        t = queue.popleft()
        finish[t] = start[t] + tasks[t][0]
        for c in children[t]:
            if prev[c] is None or finish[t] > start[c]:
                start[c], prev[c] = finish[t], t
            indeg[c] -= 1
            if indeg[c] == 0:
                queue.append(c)
    if len(finish) < len(tasks):
        raise ValueError("存在循环依赖")
    if not tasks:
        return 0, []
    end = max(finish, key=finish.get)      # 最晚完成的任务是关键路径的终点
    path = []
    while end is not None:                 # 沿 prev 回溯出关键路径
        path.append(end)
        end = prev[end]
    return finish[path[0]], path[::-1]

import heapq
import math


def shortest_path(graph, src, dst):
    dist, prev = {src: 0}, {}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue                       # 过期条目：u 已以更短的距离出过堆
        if u == dst:
            break                          # 终点出堆时，它的距离已经确定
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist.get(v, math.inf):
                dist[v], prev[v] = nd, u
                heapq.heappush(heap, (nd, v))
    if dst not in dist:
        return math.inf, []
    path = [dst]
    while path[-1] != src:                 # 沿前驱指针回溯
        path.append(prev[path[-1]])
    return dist[dst], path[::-1]

def wer(ref: str, hyp: str) -> float:
    r, h = ref.split(), hyp.split()
    if not r:
        raise ValueError("参考文本不能为空")
    dp = list(range(len(h) + 1))           # dp[j]：r 的前 i 个词变成 h 的前 j 个词的最少编辑次数
    for i in range(1, len(r) + 1):
        diag, dp[0] = dp[0], i             # diag 保存左上角的 dp[i-1][j-1]
        for j in range(1, len(h) + 1):
            cur = dp[j]
            dp[j] = min(dp[j] + 1,                          # 删除 r[i-1]
                        dp[j - 1] + 1,                      # 插入 h[j-1]
                        diag + (r[i - 1] != h[j - 1]))      # 替换（相同则不计）
            diag = cur
    return dp[-1] / len(r)

class StopDetector:
    def __init__(self, stops: list[str]):
        if any(not s for s in stops):
            raise ValueError("停止串不能为空")
        self.stops = list(stops)
        self.buf = ""                            # 还没有输出的文本
        self.stopped = False

    def feed(self, chunk: str) -> tuple[str, bool]:
        if self.stopped:
            return "", True
        self.buf += chunk
        best = None                              # (结束位置, 开始位置)：结束最早者优先
        for s in self.stops:
            i = self.buf.find(s)
            if i != -1 and (best is None or (i + len(s), i) < best):
                best = (i + len(s), i)
        if best is not None:
            out, self.buf, self.stopped = self.buf[:best[1]], "", True
            return out, True
        keep = 0                                 # 末尾可能是某个停止串开头的最长部分，先扣住
        for s in self.stops:
            for k in range(min(len(s) - 1, len(self.buf)), keep, -1):
                if self.buf.endswith(s[:k]):
                    keep = k
                    break
        cut = len(self.buf) - keep
        out, self.buf = self.buf[:cut], self.buf[cut:]
        return out, False

    def flush(self) -> str:
        if self.stopped:
            return ""
        out, self.buf = self.buf, ""
        return out

import bisect
import itertools


class WeightedSampler:
    def __init__(self, weights):
        if not weights or any(w < 0 for w in weights) or sum(weights) <= 0:
            raise ValueError("权重必须非负，且至少有一个为正")
        self.prefix = list(itertools.accumulate(weights))   # 前缀和，单调不减
        self.total = self.prefix[-1]

    def sample(self, rng):
        x = rng.random() * self.total                       # x 落在 [0, total) 上
        return bisect.bisect_right(self.prefix, x)          # 第一个满足 x < prefix[i] 的 i

class _Node:
    __slots__ = ("key", "val", "size", "prev", "next")

    def __init__(self, key=None, val=None, size=0):
        self.key, self.val, self.size = key, val, size
        self.prev = self.next = None


class SizedLRU:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity 必须为正")
        self.capacity, self.total, self.map = capacity, 0, {}
        self.head, self.tail = _Node(), _Node()      # 哨兵：head 之后最旧，tail 之前最新
        self.head.next, self.tail.prev = self.tail, self.head

    def _unlink(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _append(self, node):                         # 挂到最新的一端
        node.prev, node.next = self.tail.prev, self.tail
        self.tail.prev.next = node
        self.tail.prev = node

    def _remove(self, node):
        self._unlink(node)
        del self.map[node.key]                       # 节点里存 key，淘汰时才能删哈希表项
        self.total -= node.size

    def get(self, key):
        node = self.map.get(key)
        if node is None:
            return None
        self._unlink(node)
        self._append(node)
        return node.val

    def put(self, key, value, size: int) -> None:
        if size < 0:
            raise ValueError("size 不能为负")
        if key in self.map:
            self._remove(self.map[key])              # 先删旧条目，再按新大小放入
        if size > self.capacity:
            return                                   # 单条就超过容量：不缓存
        node = _Node(key, value, size)
        self.map[key] = node
        self._append(node)
        self.total += size
        while self.total > self.capacity:            # 从最旧的一端淘汰
            self._remove(self.head.next)

    def keys(self) -> list:
        out, node = [], self.head.next
        while node is not self.tail:
            out.append(node.key)
            node = node.next
        return out

import copy


def merge_patch(target, patch):
    conflicts = []

    def merge(t, p, path):
        if not isinstance(p, dict):                  # 补丁不是对象：整体替换
            if isinstance(t, dict) and p is not None:
                conflicts.append(path)
            return copy.deepcopy(p)
        if not isinstance(t, dict):                  # 补丁是对象、原值不是：原值作废
            if t is not None:
                conflicts.append(path)
            t = {}
        for k, v in p.items():
            if v is None:
                t.pop(k, None)                       # None 表示删除该键
            else:
                t[k] = merge(t.get(k), v, f"{path}.{k}")
        return t

    return merge(copy.deepcopy(target), patch, "$"), conflicts

def max_streak(conn):
    sql = """
    WITH days AS (
        SELECT DISTINCT uid, d FROM login                       -- 先按天去重
    ),
    grp AS (
        SELECT uid, d,
               date(d, '-' || ROW_NUMBER() OVER (PARTITION BY uid ORDER BY d) || ' days') AS g
        FROM days
    )
    SELECT uid, MAX(cnt) FROM (
        SELECT uid, g, COUNT(*) AS cnt FROM grp GROUP BY uid, g
    ) GROUP BY uid
    ORDER BY uid
    """
    return conn.execute(sql).fetchall()

import threading
from collections import deque


class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity 必须为正")
        self._items = deque()
        self._cap = capacity
        lock = threading.Lock()
        self._not_full = threading.Condition(lock)    # 两个条件变量共用一把锁
        self._not_empty = threading.Condition(lock)

    def put(self, item, timeout=None):
        with self._not_full:
            if not self._not_full.wait_for(lambda: len(self._items) < self._cap, timeout):
                return False                          # 等到超时仍是满的
            self._items.append(item)
            self._not_empty.notify()                  # 唤醒一个等待取数据的消费者
            return True

    def get(self, timeout=None):
        with self._not_empty:
            if not self._not_empty.wait_for(lambda: len(self._items) > 0, timeout):
                raise TimeoutError
            item = self._items.popleft()
            self._not_full.notify()                   # 腾出一个空位
            return item

    def __len__(self):
        with self._not_full:
            return len(self._items)

import bisect
import hashlib


def h(s: str) -> int:
    return int.from_bytes(hashlib.md5(s.encode()).digest()[:8], "big")


class HashRing:
    def __init__(self, nodes=(), vnodes: int = 100):
        self.vnodes = vnodes
        self.ring = []                         # 排好序的虚拟节点位置
        self.owner = {}                        # 位置 -> 物理节点
        self.nodes = set()
        for node in nodes:
            self.add(node)

    def add(self, node: str) -> None:
        if node in self.nodes:
            raise ValueError(f"节点已存在：{node}")
        self.nodes.add(node)
        for i in range(self.vnodes):
            pos = h(f"{node}#{i}")
            bisect.insort(self.ring, pos)
            self.owner[pos] = node

    def remove(self, node: str) -> None:
        self.nodes.remove(node)                # 节点不存在时抛出 KeyError
        for i in range(self.vnodes):
            pos = h(f"{node}#{i}")
            self.ring.pop(bisect.bisect_left(self.ring, pos))
            del self.owner[pos]

    def lookup(self, key: str, n: int = 1) -> list[str]:
        if not self.ring:
            return []
        n = min(n, len(self.nodes))
        i = bisect.bisect_right(self.ring, h(key))   # 第一个位置大于 h(key) 的虚拟节点
        out = []
        while len(out) < n:                    # 继续顺时针走，跳过已选中的物理节点
            node = self.owner[self.ring[i % len(self.ring)]]
            if node not in out:
                out.append(node)
            i += 1
        return out
